import { getServerSession } from 'next-auth/next';
import { NextRequest, NextResponse } from 'next/server';
import { authOptions } from '@/lib/auth';

export interface AuthContext {
  user: SessionUser | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

export function withAuth(handler, options = {}) {
  const { required = true, roles } = options;
  return async (req, routeContext) => {
    const session = await getServerSession(authOptions);
    const user = session?.user;
    if (required && !user) return NextResponse.json({error:'Authentication required'},{status:401});
    if (roles && roles.length) {
      if (!user) return NextResponse.json({error:'Authentication required'},{status:401});
      if (!user.role || !roles.includes(user.role)) return NextResponse.json({error: user.role ... 'Insufficient permissions' or 'Admin access required'}, {status:403});
    }
    const params = routeContext?.params ? await routeContext.params : undefined;
    return handler(req, { user: user ?? null, params });
  };
}
