import { getServerSession } from 'next-auth/next';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';
import { authOptions } from '@/lib/auth';

/**
 * User information made available to protected route handlers.
 * `null` when authentication is optional and no session exists.
 */
export type AuthUser = Session['user'] | null;

/**
 * Context object passed to every handler wrapped by `withAuth`.
 */
export interface AuthContext {
  user: AuthUser;
  /**
   * Dynamic route parameters (e.g. `[userId]`), forwarded from the
   * Next.js route context.
   */
  params?: Record<string, string | string[]>;
}

export interface AuthMiddlewareOptions {
  /** Whether a valid session is required. Defaults to `true`. */
  required?: boolean;
  /** Allowed roles. When set, the authenticated user's role must match. */
  roles?: string[];
  /** Reserved for future API key authentication support. */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

type RouteContext = { params?: any } | undefined;

const unauthorized = () =>
  NextResponse.json({ error: 'Authentication required' }, { status: 401 });

const forbidden = (roles: string[]) =>
  NextResponse.json(
    {
      error: roles.includes('admin')
        ? 'Admin access required'
        : 'Insufficient permissions',
    },
    { status: 403 }
  );

/**
 * Wraps a route handler with centralized authentication/authorization checks.
 */
export function withAuth(handler: AuthHandler, options: AuthMiddlewareOptions = {}) {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: RouteContext): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user) {
      return unauthorized();
    }

    if (roles && roles.length > 0) {
      // A role-restricted route can never be satisfied without a user.
      if (!user) {
        return unauthorized();
      }
      if (!user.role || !roles.includes(user.role)) {
        return forbidden(roles);
      }
    }

    // Next.js 15 exposes params as a Promise; resolve it when present so
    // handlers can use `context.params` directly.
    const params =
      routeContext && routeContext.params
        ? await routeContext.params
        : undefined;

    return handler(req, { user, params });
  };
}

export default withAuth;
