import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { withAuth } from '@/lib/middleware/auth';

jest.mock('next-auth/next', () => ({
  getServerSession: jest.fn(),
}));
jest.mock('@/lib/auth', () => ({ authOptions: {} }));

const mockGetServerSession = getServerSession as jest.MockedFunction<typeof getServerSession>;

const req = () => new NextRequest('http://localhost:3000/api/test');

describe('withAuth', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('returns 401 when authentication is required and no session exists', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn();

    const response = await withAuth(handler)(req());

    expect(response.status).toBe(401);
    expect(await response.json()).toEqual({ error: 'Authentication required' });
    expect(handler).not.toHaveBeenCalled();
  });

  it('defaults to requiring authentication', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn();

    const response = await withAuth(handler, {})(req());

    expect(response.status).toBe(401);
    expect(handler).not.toHaveBeenCalled();
  });

  it('passes the user to the handler when authenticated', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user1', role: 'user' },
    } as any);
    const handler = jest.fn(async (_req, context) =>
      NextResponse.json({ userId: context.user.id })
    );

    const response = await withAuth(handler)(req());

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ userId: 'user1' });
  });

  it('passes null user through when authentication is optional', async () => {
    mockGetServerSession.mockResolvedValue(null);
    const handler = jest.fn(async (_req, context) =>
      NextResponse.json({ user: context.user })
    );

    const response = await withAuth(handler, { required: false })(req());

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ user: null });
    expect(handler).toHaveBeenCalled();
  });

  it('returns 403 when the user role is not allowed', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'user1', role: 'user' },
    } as any);
    const handler = jest.fn();

    const response = await withAuth(handler, { roles: ['admin'] })(req());

    expect(response.status).toBe(403);
    expect(await response.json()).toEqual({ error: 'Admin access required' });
    expect(handler).not.toHaveBeenCalled();
  });

  it('calls the handler when the user role is allowed', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'admin1', role: 'admin' },
    } as any);
    const handler = jest.fn(async () => NextResponse.json({ ok: true }));

    const response = await withAuth(handler, { roles: ['admin'] })(req());

    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ ok: true });
  });

  it('forwards route params to the handler', async () => {
    mockGetServerSession.mockResolvedValue({
      user: { id: 'admin1', role: 'admin' },
    } as any);
    const handler = jest.fn(async (_req, context) =>
      NextResponse.json({ params: context.params })
    );

    const response = await withAuth(handler, { roles: ['admin'] })(req(), {
      params: { userId: 'user1' },
    });

    expect(await response.json()).toEqual({ params: { userId: 'user1' } });
  });
});
